/* Supabase authentication. Client UI is not the authorization boundary: see SQL RLS/RPC. */
const KimAuth=(()=>{
 let client=null,current=null,profile=null,busy=false,generation=0,recovering=false;
 const gate=()=>document.getElementById('authGate');
 const message=s=>{const n=document.getElementById('authMessage');if(n)n.textContent=s;};
 function shell(body){gate().hidden=false;document.body.classList.add('locked');gate().innerHTML=`<div class="auth-card"><div class="brand">KiM<span>apka draw</span><sup>0,3</sup></div><small>powered by KiM Silesia</small>${body}<p id="authMessage" class="auth-message" role="status" aria-live="polite"></p></div>`;}
 function form(){shell(`<h1>Twoje pomiary.<br>Twoja przestrzeń.</h1><p>Zaloguj się, aby otworzyć swoje projekty na telefonie, tablecie i komputerze.</p><form id="authForm"><label for="authEmail">Adres e-mail</label><input id="authEmail" type="email" autocomplete="username" required maxlength="254"><label for="authPassword">Hasło</label><input id="authPassword" type="password" autocomplete="current-password" required minlength="12"><div class="auth-actions"><button class="primary" type="submit">Zaloguj się</button><button type="button" id="signupButton">Utwórz konto</button><button type="button" id="resetButton">Nie pamiętam hasła</button></div></form><p class="auth-note">Beta zamknięta: nowe konto zatwierdza administrator. Sesja trwa w tej karcie. Pomiary są przechowywane na Twoim koncie, a kopię możesz pobrać jako JSON.</p>`);
 document.getElementById('authForm').onsubmit=e=>{e.preventDefault();run('login');};document.getElementById('signupButton').onclick=()=>run('signup');document.getElementById('resetButton').onclick=()=>run('reset');}
 function lock(){generation++;projectReady=false;clearTimeout(saveTimer);ProjectStore.disconnect();dirty=false;current=null;profile=null;data={name:'',rooms:[],links:[]};roomId='';activeElement=null;shapeDraft=null;photoValue='';photoOwner=null;deletedElement=null;document.getElementById('content').replaceChildren();document.getElementById('rooms').replaceChildren();document.getElementById('mobileRooms').replaceChildren();document.getElementById('projectName').textContent='';document.getElementById('dialog').close();document.getElementById('dialogContent').replaceChildren();document.querySelector('.report')?.remove();document.getElementById('adminButton').hidden=true;}
 async function run(mode){if(busy)return;const email=document.getElementById('authEmail'),password=document.getElementById('authPassword');if(!email.reportValidity()||(mode!=='reset'&&!password.reportValidity()))return;busy=true;message('Łączenie…');try{let result;
 if(mode==='reset'){result=await client.auth.resetPasswordForEmail(email.value.trim(),{redirectTo:location.origin+location.pathname});if(result.error)throw result.error;message('Jeśli konto istnieje, otrzymasz wiadomość z instrukcją zmiany hasła.');}
 else if(mode==='signup'){result=await client.auth.signUp({email:email.value.trim(),password:password.value,options:{emailRedirectTo:location.origin+location.pathname}});if(result.error)throw result.error;if(result.data.session)await enter(result.data.session);else message('Sprawdź pocztę i potwierdź adres. Następnie zaczekaj na zatwierdzenie konta przez administratora.');}
 else {result=await client.auth.signInWithPassword({email:email.value.trim(),password:password.value});if(result.error)throw result.error;await enter(result.data.session);}
 }catch(e){message('Nie udało się wykonać operacji. Sprawdź dane i połączenie. '+(e.message||''));}finally{busy=false;}}
 function emptyProject(){return normalizeProject({id:uid(),name:'Nowa inwentaryzacja',rooms:[{id:uid(),name:'Pomieszczenie 1',w:4000,d:3000,h:2700,x:500,y:500,elements:[]}],links:[]});}
 async function enter(session){if(!session){lock();form();return;}const turn=++generation;current=session.user;
 const result=await client.from('kim_profiles').select('id,email,role,status').eq('id',current.id).single();if(turn!==generation)return;if(result.error)throw Error('Nie można odczytać profilu. Sprawdź konfigurację bazy.');profile=result.data;
 if(profile.status!=='active'){shell(`<h1>${profile.status==='pending'?'Konto czeka na zatwierdzenie':'Konto jest zablokowane'}</h1><p>${esc(profile.email)}</p><p>Dostęp do pomiarów wymaga aktywnego konta.</p><button onclick="KimAuth.refresh()">Sprawdź status</button><button onclick="KimAuth.logout()">Wyloguj</button>`);return;}
 ProjectStore.connect(client,current.id);const projects=await ProjectStore.list();if(turn!==generation)return;const next=projects.length?normalizeProject(await ProjectStore.get(projects[0].id)):emptyProject();if(turn!==generation)return;
 data=next;roomId=data.rooms[0].id;wall=0;view='wall';activeElement=null;shapeDraft=null;projectReady=true;dirty=!projects.length;gate().hidden=true;gate().replaceChildren();document.body.classList.remove('locked');document.getElementById('adminButton').hidden=profile.role!=='admin';render();status(projects.length?'● Projekt z chmury':'● Nowy projekt — zapisz pomiary');}
 async function logout(){if(busy)return;busy=true;try{if(dirty&&!await persistProject()){if(!confirm('Masz niezapisane zmiany. Anuluj i pobierz eksport JSON, aby je zachować. Wylogować i odrzucić zmiany?'))return;}await writeChain.catch(()=>{});const {error}=await client.auth.signOut({scope:'local'});if(error)throw error;lock();form();}catch{toast('Nie udało się wylogować. Sprawdź połączenie i spróbuj ponownie.');}finally{busy=false;}}
 async function refresh(){try{const {data:s,error}=await client.auth.getSession();if(error)throw error;await enter(s.session);}catch(e){message(e.message);}}
 async function admin(){try{const {data:users,error}=await client.rpc('kim_admin_users');if(error)throw error;modal(`<h2>Panel administratora</h2><p class="admin-summary">${users.length} kont (maks. 1000 na liście) · ${users.filter(u=>u.status==='pending').length} oczekujących<br>Panel zarządza dostępem. Nie pokazuje cudzych pomiarów.</p>${users.map(u=>`<div class="account-row"><div><b>${esc(u.email)}</b><small>${esc(u.role)} · ${esc(({pending:'oczekuje',active:'aktywne',suspended:'zablokowane'})[u.status])} · projekty: ${Number(u.projects)}</small></div>${u.role==='admin'?'<span>Administrator</span>':`<button data-account="${esc(u.id)}" data-status="${u.status==='active'?'suspended':'active'}">${u.status==='active'?'Zablokuj':'Zatwierdź / odblokuj'}</button>`}</div>`).join('')}<div class="dialog-actions"><button onclick="closeDialog()">Zamknij</button></div>`);document.querySelectorAll('[data-account]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const {error}=await client.rpc('kim_admin_status',{p_id:b.dataset.account,p_status:b.dataset.status});if(error)throw error;await admin();}catch{toast('Nie udało się zmienić dostępu.');b.disabled=false;}});}catch{toast('Panel niedostępny. Wymagane aktywne konto administratora.');}}
 async function reload(){if(!projectReady)return;if(dirty&&!confirm('Wczytać wersję z chmury i odrzucić niezapisane zmiany? Przedtem możesz anulować i wyeksportować JSON.'))return;clearTimeout(saveTimer);await writeChain.catch(()=>{});try{const next=normalizeProject(await ProjectStore.get(data.id));data=next;roomId=data.rooms[0].id;activeElement=null;shapeDraft=null;wall=0;dirty=false;revision++;closeDialog();render();status('● Wczytano aktualną wersję z chmury');}catch(e){toast(e.message);}}
 function recovery(){recovering=true;projectReady=false;shell('<h1>Ustaw nowe hasło</h1><form id="recoveryForm"><label for="newPassword">Hasło · minimum 12 znaków</label><input id="newPassword" type="password" autocomplete="new-password" required minlength="12"><button class="primary">Zapisz nowe hasło</button></form>');document.getElementById('recoveryForm').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;try{const {error}=await client.auth.updateUser({password:document.getElementById('newPassword').value});if(error)throw error;recovering=false;await client.auth.signOut({scope:'local'});lock();form();message('Hasło zmienione. Zaloguj się ponownie.');}catch{message('Nie udało się zmienić hasła. Otwórz nowy link z poczty i spróbuj ponownie.');}finally{busy=false;}};}
 async function start(){const c=window.KIM_CONFIG||{};if(!c.supabaseUrl||!c.supabasePublishableKey){shell('<h1>Beta 0.3 przygotowana</h1><p>Logowanie czeka na podłączenie bazy Supabase. Pomiarów nie zapisujemy w publicznym repozytorium GitHub.</p><p class="auth-note">Administrator: wykonaj migrację SQL i uzupełnij publiczne ustawienia w config.js zgodnie z README. To ekran konfiguracji — konta jeszcze nie działają.</p>');return;}
 try{if(!/^https:\/\//.test(c.supabaseUrl)||c.supabasePublishableKey.startsWith('sb_secret_'))throw Error('Nieprawidłowa konfiguracja publiczna.');client=window.KimSupabase.createClient(c.supabaseUrl,c.supabasePublishableKey,{auth:{storage:sessionStorage,persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce'}});
 client.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){lock();form();}if(event==='PASSWORD_RECOVERY')recovery();});
 const {data:s,error}=await client.auth.getSession();if(error)throw error;if(!recovering)await enter(s.session);
 }catch(e){shell('<h1>Nie udało się połączyć</h1><p>Sprawdź konfigurację i połączenie z bazą.</p><button onclick="location.reload()">Ponów</button>');message(e.message);}}
 start();return {logout,admin,refresh,reload};
})();
